const routeInfo = {
 'rute-indonesia':{title:'Rute Indonesia',kicker:'KATALOG JGTC REBORN',desc:'Jelajahi rute Trainz bertema perkeretaapian Indonesia.',category:'Rute Indonesia'},
 'session-freeware':{title:'Session Freeware',kicker:'SESSION GRATIS',desc:'Session gratis untuk rute Trainz. Periksa kebutuhan rute dan dependency.',category:'Session Freeware'},
 'session-payware':{title:'Session Payware',kicker:'SESSION PREMIUM',desc:'Session berbayar. Harga dan metode pembelian harus berasal dari admin/pembuat resmi.',category:'Session Payware'},
 'konten-freeware':{title:'Konten Freeware',kicker:'KOLEKSI GRATIS',desc:'Koleksi add-on gratis untuk Trainz Simulator.',category:'Konten Freeware'},
 'indonesia':{title:'Rute Indonesia',kicker:'KATALOG JGTC REBORN',desc:'Jelajahi rute Trainz bertema perkeretaapian Indonesia.',category:'Rute Indonesia'},
 'session-route':{title:'Session Route',kicker:'SESI PERJALANAN',desc:'Pilih session dan periksa rute serta dependency yang dibutuhkan.',categoryPrefix:'Session'},
 'freeware':{title:'Konten Freeware',kicker:'KOLEKSI GRATIS',desc:'Kumpulan konten gratis untuk Trainz Simulator.',category:'Konten Freeware'},
 'premium':{title:'Session Payware',kicker:'KOLEKSI PREMIUM',desc:'Koleksi berbayar. Isi harga dan tautan pembelian resmi.',category:'Session Payware'}
};
const main = document.querySelector('#main');
const homeMarkup = main.innerHTML;
const toast = (msg)=>{const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(window._toastTimer);window._toastTimer=setTimeout(()=>el.classList.remove('show'),3000)};
const escapeHtml = s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl = s => { try { const u = new URL(s, location.href); return ['http:','https:'].includes(u.protocol) ? u.href : (s.startsWith('#') ? s : ''); } catch { return ''; } };
function getAddons(){try{const d=JSON.parse(localStorage.getItem(STORAGE_KEY));return Array.isArray(d)?d:starterAddons.map(x=>({...x}))}catch{return starterAddons.map(x=>({...x}))}}
let addons=getAddons();
let catalogFromCloud=false;
function saveAddons(){localStorage.setItem(STORAGE_KEY,JSON.stringify(addons));}
function refreshAdminNav(){const link=document.querySelector('.admin-nav-link');if(link)link.hidden=!(window.JGTCFirebase&&window.JGTCFirebase.isAdmin);}
function imgFor(a){return escapeHtml(a.image||'assets/railway-scene.svg')}
function isPayware(a){return String(a.status||'').toLowerCase().includes('payware') || (a.price && String(a.price).trim()!=='');}
function addonCard(a){return `<article class="addon-card"><div class="addon-image"><img loading="lazy" src="${imgFor(a)}" alt="${escapeHtml(a.title)}" onerror="this.src='assets/railway-scene.svg'"><span class="pill">${escapeHtml(a.status||a.category)}</span></div><div class="addon-body"><h3>${escapeHtml(a.title)}</h3><p>${escapeHtml(a.desc)}</p><div class="addon-extra">${a.kuid?`<span><b>KUID:</b> ${escapeHtml(a.kuid)}</span>`:''}${a.version?`<span><b>Trainz:</b> ${escapeHtml(a.version)}</span>`:''}${a.routeVersion?`<span><b>Versi rute:</b> ${escapeHtml(a.routeVersion)}</span>`:''}${a.price?`<span><b>Harga:</b> ${escapeHtml(a.price)}</span>`:''}</div><div class="addon-meta"><span>${escapeHtml(a.category)}${a.date?' · '+escapeHtml(a.date):''}</span><button class="mini-btn" type="button" data-product="${escapeHtml(a.id)}">Detail produk ↗</button></div>${a.isSample?'<small class="sample-note">Konten contoh — ubah atau hapus melalui Panel Admin.</small>':''}</div></article>`}
function pageShell(title,kicker,desc,body){return `<div class="content-page"><section class="page-hero"><span class="section-kicker">${escapeHtml(kicker)}</span><h1>${escapeHtml(title)}</h1><p>${escapeHtml(desc)}</p></section>${body}</div>${footerMarkup()}`}
function footerMarkup(){return `<footer class="footer"><a class="footer-brand" href="#home"><img src="assets/jgtc-reborn.svg" alt=""> JGTC REBORN</a><p>Komunitas add-on Trainz Simulator.</p><div class="footer-bottom"><span>© ${new Date().getFullYear()} JGTC REBORN</span><span>Dibuat untuk para penggemar kereta api.</span></div></footer>`}
function cardList(list){return list.length?list.map(addonCard).join(''):'<div class="empty-state">Belum ada konten. Admin dapat menambahkan item melalui Panel Admin.</div>'}
function catalogPage(route){const info=routeInfo[route];let list=addons.filter(a=>info.category?a.category===info.category:info.categoryPrefix?a.category.toLowerCase().includes('session'):true);const filters=['Semua',...categories.map(c=>c.name)];const body=`<div class="catalog-toolbar"><div class="page-tools">${filters.map((x,i)=>`<button class="filter-button ${i===0?'active':''}" data-filter="${escapeHtml(x)}">${i===0?'Semua konten':escapeHtml(x)}</button>`).join('')}</div><label class="catalog-search"><span>⌕</span><input id="catalogSearch" type="search" placeholder="Cari nama, KUID, versi..." aria-label="Cari katalog"></label></div><div class="catalog-grid" id="catalogGrid">${cardList(list)}</div><div class="info-panel"><h2>Catatan sebelum memasang</h2><ul><li>Periksa versi Trainz Simulator yang didukung.</li><li>Pastikan semua dependency/KUID tersedia.</li><li>Ikuti ketentuan penggunaan dan distribusi pembuat konten.</li></ul></div>`;return pageShell(info.title,info.kicker,info.desc,body)}
function toolsPage(){return pageShell('Alat Bantu KUID','TOOLS & RESOURCE','Referensi untuk membantu mencari KUID dan mengelola add-on Trainz.',`<div class="external-list">${tools.map(t=>`<a class="external-link" href="${t.url}" ${t.url.startsWith('#')?'':'target="_blank" rel="noopener"'}><div><b>${escapeHtml(t.title)}</b><small>${escapeHtml(t.desc)}</small></div><span>↗</span></a>`).join('')}</div><div class="info-panel"><h2>Tips mencari dependency</h2><ol><li>Buka Content Manager, lalu cari aset yang missing dependency.</li><li>Salin KUID lengkap.</li><li>Cari pada basis data atau forum tepercaya.</li><li>Hormati lisensi pembuat konten.</li></ol></div>`)}
function tipsPage(){return pageShell('Tips Instalasi','PANDUAN TRAINZ','Panduan dasar memasang add-on dan memeriksa dependency.',`<div class="info-panel"><h2>1. Sebelum instalasi</h2><ul><li>Pastikan versi Trainz Simulator sesuai.</li><li>Baca petunjuk instalasi dari pembuat.</li><li>Cadangkan file penting.</li></ul></div><div class="info-panel"><h2>2. Memasang file CDP</h2><ol><li>Buka Content Manager.</li><li>Impor file .cdp sesuai fitur pada versi Trainz kamu.</li><li>Periksa status aset setelah impor.</li><li>Jika dependency hilang, catat KUID yang disebutkan.</li></ol></div><div class="info-panel"><h2>3. Catatan keamanan</h2><p>Unduh dari pembuat atau situs tepercaya. Jangan membagikan file berlisensi tanpa izin.</p></div>`)}
function contactPage(){return pageShell('Hubungi Admin','KONTAK & KONTRIBUSI','Tambahkan kontak resmi JGTC REBORN sebelum website dipublikasikan.',`<div class="info-panel"><h2>Kontak admin</h2><p>Kontak resmi belum diatur. Tambahkan email atau tautan komunitas pada file index.html sebelum publikasi.</p></div><div class="info-panel"><h2>Kontribusi konten</h2><p>Siapkan nama add-on, gambar, deskripsi, kategori, KUID, versi Trainz, dan tautan resmi.</p></div>`)}
function searchPage(q){const results=addons.filter(a=>(a.title+' '+a.desc+' '+a.category+' '+a.kuid+' '+a.version).toLowerCase().includes(q.toLowerCase()));return pageShell('Hasil Pencarian','PENCARIAN',`Kata kunci: “${q}”`,`<div class="catalog-grid">${cardList(results)}</div>`)}
function legacyAdminPage(){
  const fb=window.JGTCFirebase;
  if(!fb || !fb.enabled || !fb.isAdmin){
    const message=!fb||!fb.configured?'Firebase belum dikonfigurasi. Lengkapi firebase-config.js mengikuti PETUNJUK-FIREBASE.md.':'Silakan login menggunakan akun admin JGTC REBORN.';
    return pageShell('Login Admin','AKSES TERBATAS','Panel pengelolaan hanya tersedia untuk admin yang terdaftar.',`<div class="info-panel admin-login-panel"><h2>Masuk ke Panel Admin</h2><p>${escapeHtml(message)}</p><form id="adminLoginForm" class="admin-form"><label>Email admin<input id="adminEmail" type="email" autocomplete="username" required placeholder="email-admin@example.com"></label><label>Password<input id="adminPassword" type="password" autocomplete="current-password" required placeholder="Password akun Firebase"></label><div class="admin-actions"><button class="button button-primary" type="submit">Login Admin</button><a class="button button-secondary" href="#home">Kembali</a></div><p id="loginError" class="small" role="alert"></p></form></div>`);
  }
  return pageShell('Panel Admin','PENGELOLAAN KONTEN',catalogFromCloud?'Database online aktif · perubahan tersinkron real-time.':'Terhubung ke Firebase. Menunggu data katalog...',`<div class="admin-warning"><b>Mode database online:</b> perubahan disimpan ke Cloud Firestore dan dapat dilihat pengunjung setelah tersinkron. Jangan bagikan akun admin. <button class="mini-btn" id="logoutAdmin" type="button">Keluar</button></div><div class="admin-layout"><form class="admin-form" id="addonForm"><h2 id="formTitle">Tambah add-on</h2><input type="hidden" id="addonId"><label>Nama add-on *<input id="fTitle" required maxlength="120" placeholder="Contoh: Rute Daop 8 Surabaya"></label><label>Kategori *<select id="fCategory" required>${categories.map(c=>`<option>${c.name}</option>`).join('')}</select></label><label>Deskripsi<textarea id="fDesc" rows="3" maxlength="800" placeholder="Deskripsi add-on dan informasi penting"></textarea></label><label>URL gambar<input id="fImage" placeholder="assets/train-indonesia.svg atau URL gambar"></label><label>KUID<input id="fKuid" placeholder="Contoh: kuid:123456:10001"></label><label>Versi Trainz / kompatibilitas<input id="fVersion" placeholder="Contoh: TRS19 / TRS22"></label><label>Versi rute / produk<input id="fRouteVersion" placeholder="Contoh: 1.0 / 2.1"></label><label>Dependency / kebutuhan<textarea id="fRequirements" rows="2" placeholder="Rute, asset, atau dependency yang dibutuhkan"></textarea></label><div class="admin-two"><label>Status<select id="fStatus"><option>Freeware</option><option>Payware</option></select></label><label>Harga (opsional)<input id="fPrice" placeholder="Contoh: Rp25.000"></label></div><label>Tautan detail/download eksternal (HTTPS)<input id="fUrl" type="url" placeholder="https://..."></label><label>Path file privat Firebase Storage<input id="fDownloadPath" placeholder="product-files/nama-file.zip"></label><label>Tanggal rilis/update<input id="fDate" placeholder="Contoh: 30/10/2026"></label><div class="admin-actions"><button class="button button-primary" type="submit">Simpan ke Firebase</button><button class="button button-secondary" type="button" id="cancelEdit">Bersihkan</button></div></form><div class="admin-list-wrap"><div class="admin-list-head"><h2>Daftar katalog <span id="adminCount">${addons.length}</span></h2><div class="admin-actions"><button class="button button-secondary" id="exportBtn" type="button">Ekspor JSON</button><button class="button button-secondary" id="importBtn" type="button">Impor JSON</button><input type="file" id="importFile" accept="application/json,.json" hidden></div></div><div class="admin-list" id="adminList">${adminRows()}</div><p class="muted small">Ekspor JSON untuk membuat cadangan. Impor akan menambahkan atau memperbarui dokumen dengan ID yang sama; dokumen lain tidak dihapus.</p></div></div><section class="section-block payment-admin" id="paymentAdminPanel"><div class="section-heading"><div><span class="section-kicker">TRANSAKSI</span><h2>Pengaturan pembayaran</h2></div></div><div class="admin-layout"><form class="admin-form" id="paymentSettingsForm"><h2>Rekening pembayaran</h2><label><span><input type="checkbox" id="paymentEnabled" style="width:auto"> Aktifkan pembayaran manual</span></label><label>Jenis / nama bank atau e-wallet<input id="paymentMethodName" placeholder="BCA / DANA / GoPay"></label><label>Nomor rekening / akun<input id="paymentAccountNumber" placeholder="Nomor rekening atau nomor e-wallet"></label><label>Atas nama<input id="paymentAccountName" placeholder="Nama pemilik rekening"></label><label>Instruksi tambahan<textarea id="paymentInstructions" rows="3" maxlength="1000" placeholder="Cantumkan nominal tepat dan nomor pesanan pada berita transfer."></textarea></label><button class="button button-primary" type="submit">Simpan pengaturan pembayaran</button><p id="paymentSettingsMessage" class="small" role="status"></p></form><div class="admin-list-wrap"><div class="admin-list-head"><h2>Verifikasi pembayaran</h2><button class="button button-secondary" id="refreshPayments" type="button">Muat ulang</button></div><div id="pendingPayments" class="admin-list"><div class="empty-state">Memuat pembayaran...</div></div></div></div></section>`)
}
function adminRows(){return addons.map(a=>`<article class="admin-row"><div><b>${escapeHtml(a.title)}</b><small>${escapeHtml(a.category)} · ${escapeHtml(a.status||'')}</small>${a.isSample?'<em>Konten contoh</em>':''}</div><div class="admin-row-actions"><button type="button" class="mini-btn" data-edit="${escapeHtml(a.id)}">Edit</button><button type="button" class="mini-btn danger" data-delete="${escapeHtml(a.id)}">Hapus</button></div></article>`).join('')||'<div class="empty-state">Belum ada item katalog.</div>'}
function legacyBindAdmin(){
  const fb=window.JGTCFirebase;
  const loginForm=document.querySelector('#adminLoginForm');
  if(loginForm){loginForm.addEventListener('submit',async e=>{e.preventDefault();const error=document.querySelector('#loginError');error.textContent='Memproses login...';try{await fb.login(document.querySelector('#adminEmail').value.trim(),document.querySelector('#adminPassword').value);refreshAdminNav();render();}catch(err){error.textContent=err.message||'Login gagal. Periksa email dan password.';}});return;}
  const form=document.querySelector('#addonForm');if(!form)return;
  document.querySelector('#logoutAdmin').addEventListener('click',async()=>{try{await fb.logout();location.hash='home';refreshAdminNav();render();}catch(e){toast(e.message)}});
  form.addEventListener('submit',async e=>{e.preventDefault();const id=document.querySelector('#addonId').value||('addon-'+Date.now());const item={id,title:document.querySelector('#fTitle').value.trim(),category:document.querySelector('#fCategory').value,desc:document.querySelector('#fDesc').value.trim(),image:document.querySelector('#fImage').value.trim()||'assets/railway-scene.svg',kuid:document.querySelector('#fKuid').value.trim(),version:document.querySelector('#fVersion').value.trim(),routeVersion:document.querySelector('#fRouteVersion').value.trim(),requirements:document.querySelector('#fRequirements').value.trim(),status:document.querySelector('#fStatus').value,price:document.querySelector('#fPrice').value.trim(),url:document.querySelector('#fUrl').value.trim(),downloadPath:document.querySelector('#fDownloadPath').value.trim(),date:document.querySelector('#fDate').value.trim(),isSample:false};if(item.url&&!safeUrl(item.url)){toast('URL harus menggunakan http atau https.');return}try{await fb.save(item);form.reset();document.querySelector('#addonId').value='';document.querySelector('#formTitle').textContent='Tambah add-on';toast('Add-on tersimpan ke Firebase.');}catch(err){toast('Gagal menyimpan: '+err.message)}});
  document.querySelector('#cancelEdit').addEventListener('click',()=>{form.reset();document.querySelector('#addonId').value='';document.querySelector('#formTitle').textContent='Tambah add-on'});
  document.querySelector('#exportBtn').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(addons,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='jgtc-reborn-katalog.json';a.click();URL.revokeObjectURL(url);toast('File cadangan JSON dibuat.')});
  document.querySelector('#importBtn').addEventListener('click',()=>document.querySelector('#importFile').click());
  document.querySelector('#importFile').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{const d=JSON.parse(await f.text());if(!Array.isArray(d)||d.some(x=>!x.title||!x.category))throw new Error('Format katalog tidak sesuai');await fb.replaceAll(d.map((x,i)=>({...x,id:String(x.id||'import-'+Date.now()+'-'+i)})));toast('Katalog berhasil dikirim ke Firebase.');}catch(err){toast('Gagal impor: '+err.message)}e.target.value=''});
  document.querySelector('#adminList').addEventListener('click',async e=>{const edit=e.target.closest('[data-edit]');const del=e.target.closest('[data-delete]');if(edit){const a=addons.find(x=>x.id===edit.dataset.edit);if(!a)return;document.querySelector('#addonId').value=a.id;document.querySelector('#fTitle').value=a.title||'';document.querySelector('#fCategory').value=a.category||categories[0].name;document.querySelector('#fDesc').value=a.desc||'';document.querySelector('#fImage').value=a.image||'';document.querySelector('#fKuid').value=a.kuid||'';document.querySelector('#fVersion').value=a.version||'';document.querySelector('#fRouteVersion').value=a.routeVersion||'';document.querySelector('#fRequirements').value=a.requirements||'';document.querySelector('#fStatus').value=a.status||'Freeware';document.querySelector('#fPrice').value=a.price||'';document.querySelector('#fUrl').value=a.url||'';document.querySelector('#fDownloadPath').value=a.downloadPath||'';document.querySelector('#fDate').value=a.date||'';document.querySelector('#formTitle').textContent='Edit add-on';document.querySelector('#fTitle').focus();window.scrollTo({top:0,behavior:'smooth'})}if(del){const a=addons.find(x=>x.id===del.dataset.delete);if(a&&confirm(`Hapus "${a.title}" dari katalog online?`)){try{await fb.remove(a.id);toast('Item dihapus dari Firebase.')}catch(err){toast('Gagal menghapus: '+err.message)}}}});
}
async function bindPaymentAdmin(){
 const fb=window.JGTCFirebase, form=document.querySelector('#paymentSettingsForm'); if(!form||!fb?.isAdmin)return;
 const msg=document.querySelector('#paymentSettingsMessage');
 try{const cfg=await fb.getPaymentSettings();document.querySelector('#paymentEnabled').checked=!!cfg.enabled;document.querySelector('#paymentInstructions').value=cfg.instructions||'';const first=(cfg.methods||[])[0]||{};document.querySelector('#paymentMethodName').value=first.name||'';document.querySelector('#paymentAccountNumber').value=first.accountNumber||'';document.querySelector('#paymentAccountName').value=first.accountName||cfg.accountName||'';}catch(e){msg.textContent=e.message}
 form.addEventListener('submit',async e=>{e.preventDefault();msg.textContent='Menyimpan...';try{await fb.savePaymentSettings({enabled:document.querySelector('#paymentEnabled').checked,methods:[{type:'bank',name:document.querySelector('#paymentMethodName').value,accountNumber:document.querySelector('#paymentAccountNumber').value,accountName:document.querySelector('#paymentAccountName').value}],accountName:document.querySelector('#paymentAccountName').value,instructions:document.querySelector('#paymentInstructions').value});msg.textContent='Pengaturan pembayaran berhasil disimpan.';toast('Pengaturan pembayaran disimpan.');}catch(err){msg.textContent=err.message}});
 const load=async()=>{const box=document.querySelector('#pendingPayments');box.innerHTML='<div class="empty-state">Memuat...</div>';try{const rows=await fb.getPendingPayments();box.innerHTML=rows.length?rows.map(p=>`<article class="admin-row payment-row"><div><b>${escapeHtml(p.orderNumber||p.id)}</b><small>${money(p.amount||0)} · ${escapeHtml(p.userId||'')}</small>${p.proofUrl?`<a href="${escapeHtml(p.proofUrl)}" target="_blank" rel="noopener">Lihat bukti pembayaran ↗</a>`:''}</div><div class="admin-row-actions"><button class="mini-btn" data-review="approve" data-order="${escapeHtml(p.id)}">Setujui</button><button class="mini-btn danger" data-review="reject" data-order="${escapeHtml(p.id)}">Tolak</button></div></article>`).join(''):'<div class="empty-state">Tidak ada pembayaran menunggu verifikasi.</div>';}catch(e){box.innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`}};
 document.querySelector('#refreshPayments').addEventListener('click',load);document.querySelector('#pendingPayments').addEventListener('click',async e=>{const b=e.target.closest('[data-review]');if(!b)return;const note=prompt('Catatan untuk pembeli (opsional):')||'';if(b.dataset.review==='reject'&&!note&&!confirm('Tolak pembayaran tanpa catatan?'))return;b.disabled=true;try{await fb.reviewPayment(b.dataset.order,b.dataset.review,note);toast(b.dataset.review==='approve'?'Pembayaran disetujui.':'Pembayaran ditolak.');load()}catch(err){toast(err.message);b.disabled=false}});load();
}
const CART_KEY='jgtc-reborn-cart-v1';
function getCart(){try{return JSON.parse(localStorage.getItem(CART_KEY)||'[]')}catch{return []}}
function setCart(ids){localStorage.setItem(CART_KEY,JSON.stringify([...new Set(ids)]));updateCartCount()}
function money(v){const n=Number(v)||0;return new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n)}
function priceNumber(value){const digits=String(value||'').replace(/[^0-9]/g,'');return digits?Number(digits):0}
function productDetailPage(id){const a=addons.find(x=>x.id===id);if(!a)return pageShell('Produk tidak ditemukan','KATALOG','Produk tidak tersedia.','<div class="info-panel"><a class="button button-primary" href="#home">Kembali ke katalog</a></div>');const paid=isPayware(a);const link=safeUrl(a.url||'');return pageShell(a.title,'DETAIL PRODUK',a.category,`<div class="product-detail"><div class="product-detail-image"><img src="${imgFor(a)}" alt="${escapeHtml(a.title)}"></div><div class="product-detail-info"><span class="pill">${escapeHtml(a.status||a.category)}</span><h2>${escapeHtml(a.title)}</h2><p>${escapeHtml(a.desc)}</p><div class="product-specs">${a.kuid?`<p><b>KUID:</b> ${escapeHtml(a.kuid)}</p>`:''}${a.version?`<p><b>Versi Trainz:</b> ${escapeHtml(a.version)}</p>`:''}${a.routeVersion?`<p><b>Versi rute/produk:</b> ${escapeHtml(a.routeVersion)}</p>`:''}${a.requirements?`<p><b>Dependency:</b> ${escapeHtml(a.requirements)}</p>`:''}<p><b>Kategori:</b> ${escapeHtml(a.category)}</p></div>${paid?`<div class="product-price">${escapeHtml(a.price||'Harga belum ditentukan')}</div><button class="button button-primary" type="button" data-add-cart="${escapeHtml(a.id)}">Tambah ke keranjang</button>`:`<div class="product-price">Gratis</div>${link?`<a class="button button-primary" href="${escapeHtml(link)}" target="_blank" rel="noopener">Buka tautan resmi ↗</a>`:'<p class="muted">Tautan download belum tersedia.</p>'}`}${a.category==='Rute Indonesia'?'<p><a class="button button-secondary" href="#route-updates">Lihat pilihan update rute ↗</a></p>':''}<p class="small muted">${paid?'Pembayaran dilakukan melalui transfer manual dan diverifikasi admin.':'Pastikan mengikuti ketentuan lisensi pembuat konten.'}</p></div></div>`)}
function paymentPage(orderId){const user=window.JGTCFirebase?.currentUser;if(!user)return pageShell('Login diperlukan','PEMBAYARAN','Masuk untuk melanjutkan.',`<div class="info-panel"><a class="button button-primary" href="#account">Login pembeli</a></div>`);return pageShell('Pembayaran Pesanan','TRANSFER MANUAL','Lakukan transfer sesuai instruksi admin, lalu unggah bukti pembayaran.',`<div class="checkout-layout"><section class="admin-form"><h2>Instruksi pembayaran</h2><div id="paymentInstructionsBox" class="info-panel">Memuat informasi rekening...</div><form id="paymentProofForm"><input type="hidden" id="paymentOrderId" value="${escapeHtml(orderId)}"><label>Nomor pesanan<input id="paymentOrderNumber" readonly></label><label>Unggah bukti transfer (JPG, PNG, PDF; maks. 5 MB)<input id="paymentProofFile" type="file" accept="image/jpeg,image/png,application/pdf" required></label><button class="button button-primary" id="submitPaymentProof" type="submit">Kirim bukti pembayaran</button><p id="paymentProofError" class="small" role="alert"></p></form></section><aside class="cart-summary"><h2>Ringkasan pesanan</h2><div id="paymentOrderSummary">Memuat pesanan...</div></aside></div>`)}
function accountPage(){const fb=window.JGTCFirebase;const user=fb?.currentUser;if(user)return pageShell('Akun Pembeli','AKUN SAYA','Informasi akun yang sedang masuk.',`<div class="info-panel account-panel"><div class="account-avatar">${escapeHtml((user.displayName||user.email||'P').slice(0,1).toUpperCase())}</div><h2>${escapeHtml(user.displayName||'Pelanggan JGTC')}</h2><p>${escapeHtml(user.email||'')}</p><p class="muted small">UID: ${escapeHtml(user.uid)}</p><div class="admin-actions"><a class="button button-primary" href="#orders">Riwayat pembelian</a><a class="button button-secondary" href="#route-updates">Cek update rute</a><button class="button button-secondary" id="customerLogout" type="button">Keluar</button></div></div><section class="section-block customer-dashboard"><div class="section-heading"><div><span class="section-kicker">RINGKASAN AKUN</span><h2>Dashboard pelanggan</h2></div><button class="mini-btn" id="refreshCustomerDashboard" type="button">Muat ulang</button></div><div id="customerDashboardContent" class="dashboard-grid"><div class="empty-state">Memuat ringkasan akun...</div></div></section>`);return pageShell('Akun Pembeli','LOGIN & REGISTRASI','Masuk untuk melakukan pembelian dan melihat riwayat transaksi.',`<div class="auth-grid"><form id="customerLoginForm" class="admin-form"><h2>Login</h2><label>Email<input id="customerEmail" type="email" required autocomplete="email"></label><label>Password<input id="customerPassword" type="password" required autocomplete="current-password"></label><button class="button button-primary" type="submit">Login</button><button class="button button-secondary" id="googleLogin" type="button">Lanjutkan dengan Google</button><p id="customerLoginError" class="small" role="alert"></p></form><form id="customerRegisterForm" class="admin-form"><h2>Buat akun</h2><label>Nama lengkap<input id="registerName" required maxlength="100"></label><label>Email<input id="registerEmail" type="email" required autocomplete="email"></label><label>Password<input id="registerPassword" type="password" minlength="6" required autocomplete="new-password"></label><button class="button button-primary" type="submit">Daftar</button><p id="registerError" class="small" role="alert"></p></form></div>`)}
async function ordersPage(){const fb=window.JGTCFirebase;if(!fb?.currentUser)return pageShell('Riwayat Pembelian','AKUN SAYA','Login untuk melihat transaksi.',`<div class="info-panel"><a class="button button-primary" href="#account">Login pembeli</a></div>`);return pageShell('Riwayat Pembelian','AKUN SAYA','Daftar pesanan dari akun kamu.',`<div id="ordersList" class="orders-list"><div class="empty-state">Memuat riwayat pembelian...</div></div>`)}
function legacyBindCommerce(){const fb=window.JGTCFirebase;document.querySelectorAll('[data-product]').forEach(b=>b.addEventListener('click',()=>location.hash='product?id='+encodeURIComponent(b.dataset.product)));document.querySelectorAll('[data-add-cart]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.addCart;const a=addons.find(x=>x.id===id);if(!a||!isPayware(a)||priceNumber(a.price)<=0){toast('Produk belum memiliki harga valid.');return}setCart([...getCart(),id]);toast('Produk ditambahkan ke keranjang.');location.hash='cart'}));document.querySelectorAll('[data-remove-cart]').forEach(b=>b.addEventListener('click',()=>{setCart(getCart().filter(id=>id!==b.dataset.removeCart));render()}));document.querySelector('#goCheckout')?.addEventListener('click',()=>location.hash='checkout');document.querySelector('#customerLogout')?.addEventListener('click',async()=>{await fb.logout();render()});document.querySelector('#customerLoginForm')?.addEventListener('submit',async e=>{e.preventDefault();const out=document.querySelector('#customerLoginError');out.textContent='Memproses...';try{await fb.loginCustomer(document.querySelector('#customerEmail').value.trim(),document.querySelector('#customerPassword').value);location.hash='account';render()}catch(err){out.textContent=err.message}});document.querySelector('#googleLogin')?.addEventListener('click',async()=>{try{await fb.loginGoogle();location.hash='account';render()}catch(err){document.querySelector('#customerLoginError').textContent=err.message}});document.querySelector('#customerRegisterForm')?.addEventListener('submit',async e=>{e.preventDefault();const out=document.querySelector('#registerError');out.textContent='Membuat akun...';try{await fb.register(document.querySelector('#registerEmail').value.trim(),document.querySelector('#registerPassword').value,document.querySelector('#registerName').value.trim());location.hash='account';render()}catch(err){out.textContent=err.message}});document.querySelector('#checkoutForm')?.addEventListener('submit',async e=>{e.preventDefault();const btn=document.querySelector('#createOrderBtn'),out=document.querySelector('#checkoutError');btn.disabled=true;btn.textContent='Membuat pesanan...';out.textContent='';try{const result=await fb.createOrder(getCart(),document.querySelector('#orderNote')?.value||'',getRouteCart());setCart([]);setRouteCart([]);toast('Pesanan berhasil dibuat: '+result.orderNumber);location.hash='orders'}catch(err){out.textContent=err.message||'Gagal membuat pesanan.';btn.disabled=false;btn.textContent='Buat pesanan'}});document.querySelector('#paymentProofForm')?.addEventListener('submit',async e=>{e.preventDefault();const btn=document.querySelector('#submitPaymentProof'),out=document.querySelector('#paymentProofError'),file=document.querySelector('#paymentProofFile').files[0];btn.disabled=true;out.textContent='Mengunggah bukti...';try{await fb.uploadPaymentProof(document.querySelector('#paymentOrderId').value,file);toast('Bukti pembayaran terkirim dan menunggu verifikasi.');location.hash='orders'}catch(err){out.textContent=err.message;btn.disabled=false}});if(location.hash.startsWith('#payment'))loadPaymentPage();if(location.hash.startsWith('#orders'))loadOrders();} 
async function loadPaymentPage(){const fb=window.JGTCFirebase, id=new URLSearchParams(location.hash.split('?')[1]||'').get('id');if(!id)return;try{const rows=await fb.getMyOrders(),order=rows.find(x=>x.id===id);if(!order)throw new Error('Pesanan tidak ditemukan.');document.querySelector('#paymentOrderNumber').value=order.orderNumber||order.id;document.querySelector('#paymentOrderSummary').innerHTML=`<b>${money(order.total)}</b><p>${(order.items||[]).map(i=>escapeHtml(i.title)).join(', ')}</p>`;const cfg=await fb.getPaymentSettings(),box=document.querySelector('#paymentInstructionsBox');box.innerHTML=cfg.enabled?`${(cfg.methods||[]).map(m=>`<p><b>${escapeHtml(m.name)}</b><br>${escapeHtml(m.accountNumber)}<br>Atas nama: ${escapeHtml(m.accountName||'')}</p>`).join('')}<p>${escapeHtml(cfg.instructions||'Transfer sesuai total pesanan.')}</p>`:'<b>Pembayaran belum diaktifkan admin.</b>';if(!cfg.enabled)document.querySelector('#paymentProofForm').hidden=true;if(order.status!=='awaiting_payment'&&order.paymentStatus!=='rejected')document.querySelector('#paymentProofForm').innerHTML='<p class="muted">Pesanan ini tidak sedang menunggu bukti pembayaran.</p>';}catch(err){document.querySelector('#paymentInstructionsBox').textContent=err.message}}

async function loadOrders(){const el=document.querySelector('#ordersList');if(!el)return;try{const rows=await window.JGTCFirebase.getMyOrders();el.innerHTML=rows.length?rows.map(o=>`<article class="order-card"><div><b>${escapeHtml(o.orderNumber||o.id)}</b><small>${new Date(o.createdAt?.seconds?o.createdAt.seconds*1000:Date.now()).toLocaleString('id-ID')}</small></div><strong>${money(o.total||0)}</strong><span class="order-status">${escapeHtml(o.paymentStatus==='rejected'?'Pembayaran ditolak':o.status||'Menunggu pembayaran')}</span><div class="order-products">${(o.items||[]).map(i=>escapeHtml(i.title)).join(', ')}</div><div class="admin-actions order-actions">${o.status==='awaiting_payment'?`<a class="button button-primary" href="#payment?id=${encodeURIComponent(o.id)}">Bayar sekarang / unggah bukti</a>`:''}${o.status==='awaiting_verification'?'<span class="muted small">Bukti diterima · menunggu verifikasi admin</span>':''}${o.paymentStatus==='rejected'?`<a class="button button-secondary" href="#payment?id=${encodeURIComponent(o.id)}">Unggah ulang bukti</a>`:''}${o.paymentStatus==='paid'||o.status==='paid'?`<button class="button button-secondary" data-download-order="${escapeHtml(o.id)}">Akses download</button>`:''}</div></article>`).join(''):'<div class="empty-state">Belum ada transaksi.</div>';el.onclick=async ev=>{const b=ev.target.closest('[data-download-order]');if(!b)return;b.disabled=true;try{const files=await window.JGTCFirebase.getOrderDownloads(b.dataset.downloadOrder);if(!files.length){toast('Tautan download belum disediakan admin.');return}files.forEach(f=>window.open(f.url,'_blank','noopener'));}catch(err){toast(err.message)}finally{b.disabled=false}}}catch(err){el.innerHTML=`<div class="empty-state">Tidak dapat memuat riwayat: ${escapeHtml(err.message)}</div>`}}

// ===== Tahap 5: Penjualan rute dan pembaruan versi =====
const ROUTE_CART_KEY='jgtc-reborn-route-update-cart-v1';
const ROUTE_CART_META_KEY='jgtc-reborn-route-update-cart-meta-v1';
const routeUpdateCache=new Map();
function getRouteCart(){try{return JSON.parse(localStorage.getItem(ROUTE_CART_KEY)||'[]')}catch{return []}}
function getRouteCartMeta(){try{return JSON.parse(localStorage.getItem(ROUTE_CART_META_KEY)||'{}')}catch{return {}}}
function setRouteCart(ids){const clean=[...new Set((ids||[]).map(String))];localStorage.setItem(ROUTE_CART_KEY,JSON.stringify(clean));updateCartCount()}
function saveRouteCartMeta(item){const meta=getRouteCartMeta();meta[item.id]={id:item.id,routeAddonId:item.routeAddonId,routeTitle:item.routeTitle,version:item.version,requiredPreviousVersion:item.requiredPreviousVersion,description:item.description,price:item.price};localStorage.setItem(ROUTE_CART_META_KEY,JSON.stringify(meta))}
function routeCartItems(){const meta=getRouteCartMeta();return getRouteCart().map(id=>meta[id]||{id,routeTitle:'Pilihan update perlu disinkronkan',version:'',requiredPreviousVersion:'',price:0})}
function updateCartCount(){const el=document.querySelector('#cartCount');if(el)el.textContent=getCart().length+getRouteCart().length}
let routeCartSyncing=false,routeCartSyncedAt=0;
async function refreshRouteCartMeta(currentRoute){const fb=window.JGTCFirebase;if(routeCartSyncing||!getRouteCart().length||!fb?.currentUser||Date.now()-routeCartSyncedAt<5000)return;routeCartSyncing=true;try{const updates=await fb.getRouteUpdates(),byId=new Map(updates.map(u=>[u.id,u])),ids=getRouteCart(),valid=[];for(const id of ids){const u=byId.get(id);if(u?.eligible){saveRouteCartMeta(u);valid.push(id)}}if(valid.length!==ids.length){setRouteCart(valid);toast('Pilihan update yang tidak lagi memenuhi syarat dihapus dari keranjang.')}routeCartSyncedAt=Date.now();const route=(location.hash.slice(1)||'home').split('?')[0];if(route===currentRoute)render()}catch(err){console.warn('Sinkronisasi keranjang update rute gagal:',err.message)}finally{routeCartSyncing=false}}
function routeUpdatesPage(){return pageShell('Update / Perpanjang Rute','JGTC ROUTE UPDATES','Pilih versi terbaru untuk rute yang sudah kamu miliki. Harga dan kelayakan diperiksa kembali oleh server saat checkout.','<div id="routeUpdatesList" class="route-updates-list"><div class="empty-state">Memuat pilihan update rute...</div></div>')}
async function loadRouteUpdatesPage(){const box=document.querySelector('#routeUpdatesList');if(!box)return;const fb=window.JGTCFirebase;try{const updates=await fb.getRouteUpdates();updates.forEach(x=>routeUpdateCache.set(x.id,x));box.innerHTML=updates.length?updates.map(u=>`<article class="route-update-card"><div class="route-update-copy"><span class="pill">${u.ownershipVerified?(u.owned?'RUTE DIMILIKI':'BELUM DIMILIKI'):'INFO UPDATE RUTE'}</span><h3>${escapeHtml(u.routeTitle)}</h3><p>${escapeHtml(u.description||'Pembaruan rute tersedia.')}</p><div class="route-update-meta"><span>Versi saat ini: <b>${escapeHtml(u.routeVersion||'Perlu verifikasi')}</b></span><span>Versi tujuan: <b>${escapeHtml(u.version)}</b></span><span>Harga: <b>${money(u.price)}</b></span></div>${u.ownershipVerified&&u.eligible?`<button class="button button-primary" data-add-route-update="${escapeHtml(u.id)}">Tambah update ke keranjang</button>`:!u.ownershipVerified?'<p class="small muted">Kamu dapat melihat pilihan update tanpa login. Pemeriksaan kepemilikan rute dilakukan saat proses pembelian.</p>':u.owned?'<p class="small muted">Versi rute tidak sesuai dengan persyaratan update ini.</p>':'<p class="small muted">Kamu harus memiliki rute ini terlebih dahulu.</p>'}</div></article>`).join(''):'<div class="empty-state">Belum ada pilihan update rute yang diaktifkan admin.</div>';}catch(err){box.innerHTML=`<div class="empty-state">Tidak dapat memuat update rute: ${escapeHtml(err.message)}</div>`}}
function routeUpdatesAdminMarkup(){const routeOptions=addons.filter(a=>a.category==='Rute Indonesia'&&!a.isSample).map(a=>`<option value="${escapeHtml(a.id)}">${escapeHtml(a.title)}</option>`).join('');return `<section class="section-block route-update-admin" id="routeUpdateAdminPanel"><div class="section-heading"><div><span class="section-kicker">PENJUALAN RUTE</span><h2>Manajemen update / perpanjang rute</h2></div></div><div class="admin-layout"><form class="admin-form" id="routeUpdateForm"><h3 id="routeUpdateFormTitle">Tambah pilihan update</h3><input type="hidden" id="routeUpdateId"><label>Produk rute *<select id="routeUpdateAddon" required><option value="">Pilih rute Indonesia</option>${routeOptions}</select></label><label>Versi baru *<input id="routeUpdateVersion" required maxlength="60" placeholder="Contoh: 2.0"></label><label>Versi sebelumnya yang wajib dimiliki *<input id="routeUpdatePrevious" required maxlength="60" placeholder="Contoh: 1.0"></label><label>Harga update (Rupiah) *<input id="routeUpdatePrice" required inputmode="numeric" placeholder="Contoh: 50000"></label><label>Deskripsi perubahan<textarea id="routeUpdateDescription" rows="3" maxlength="1000" placeholder="Penambahan area, stasiun, perbaikan jalur..."></textarea></label><label>Tautan download eksternal HTTPS<input id="routeUpdateUrl" type="url" placeholder="https://..."></label><label>Path file privat Firebase Storage<input id="routeUpdatePath" placeholder="product-files/update-rute-v2.zip"></label><label><span><input id="routeUpdateActive" type="checkbox" checked style="width:auto"> Aktifkan pilihan update</span></label><div class="admin-actions"><button class="button button-primary" type="submit">Simpan pilihan update</button><button class="button button-secondary" type="button" id="routeUpdateReset">Bersihkan</button></div><p id="routeUpdateMessage" class="small" role="status"></p></form><div class="admin-list-wrap"><div class="admin-list-head"><h3>Daftar pilihan update</h3><button class="button button-secondary" type="button" id="refreshRouteUpdates">Muat ulang</button></div><div id="adminRouteUpdatesList" class="admin-list"><div class="empty-state">Memuat pilihan update...</div></div></div></div><p class="muted small">Harga, kepemilikan rute, dan versi sebelumnya divalidasi ulang oleh Cloud Functions saat checkout dan saat pembayaran disetujui. Menonaktifkan pilihan tidak menghapus riwayat pesanan.</p></section>`}
function adminPage(){const html=legacyAdminPage();return window.JGTCFirebase?.isAdmin?html.replace(footerMarkup(),routeUpdatesAdminMarkup()+footerMarkup()):html}
function bindAdmin(){legacyBindAdmin();bindRouteUpdatesAdmin()}
async function bindRouteUpdatesAdmin(){const form=document.querySelector('#routeUpdateForm'),fb=window.JGTCFirebase;if(!form||!fb?.isAdmin)return;const box=document.querySelector('#adminRouteUpdatesList'),msg=document.querySelector('#routeUpdateMessage');const reset=()=>{form.reset();document.querySelector('#routeUpdateId').value='';document.querySelector('#routeUpdateFormTitle').textContent='Tambah pilihan update';document.querySelector('#routeUpdateActive').checked=true};const load=async()=>{box.innerHTML='<div class="empty-state">Memuat...</div>';try{const rows=await fb.getAdminRouteUpdates();box.innerHTML=rows.length?rows.map(u=>`<article class="admin-row"><div><b>${escapeHtml(u.routeTitle||u.routeAddonId)}</b><small>${escapeHtml(u.requiredPreviousVersion)} → ${escapeHtml(u.version)} · ${money(u.price)} · ${u.active?'Aktif':'Nonaktif'}</small><small>${escapeHtml(u.description||'')}</small></div><div class="admin-row-actions"><button class="mini-btn" data-route-edit="${escapeHtml(u.id)}">Edit</button>${u.active?`<button class="mini-btn danger" data-route-disable="${escapeHtml(u.id)}">Nonaktifkan</button>`:''}</div></article>`).join(''):'<div class="empty-state">Belum ada pilihan update rute.</div>';box._rows=rows;}catch(e){box.innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`}};form.addEventListener('submit',async e=>{e.preventDefault();const payload={id:document.querySelector('#routeUpdateId').value||undefined,routeAddonId:document.querySelector('#routeUpdateAddon').value,version:document.querySelector('#routeUpdateVersion').value.trim(),requiredPreviousVersion:document.querySelector('#routeUpdatePrevious').value.trim(),price:document.querySelector('#routeUpdatePrice').value,description:document.querySelector('#routeUpdateDescription').value.trim(),url:document.querySelector('#routeUpdateUrl').value.trim(),downloadPath:document.querySelector('#routeUpdatePath').value.trim(),active:document.querySelector('#routeUpdateActive').checked};msg.textContent='Menyimpan...';try{await fb.saveRouteUpdate(payload);msg.textContent='Pilihan update berhasil disimpan.';toast('Pilihan update rute disimpan.');reset();load()}catch(err){msg.textContent=err.message}});document.querySelector('#routeUpdateReset').addEventListener('click',reset);document.querySelector('#refreshRouteUpdates').addEventListener('click',load);box.addEventListener('click',e=>{const edit=e.target.closest('[data-route-edit]'),disable=e.target.closest('[data-route-disable]');if(edit){const u=(box._rows||[]).find(x=>x.id===edit.dataset.routeEdit);if(!u)return;document.querySelector('#routeUpdateId').value=u.id;document.querySelector('#routeUpdateAddon').value=u.routeAddonId;document.querySelector('#routeUpdateVersion').value=u.version||'';document.querySelector('#routeUpdatePrevious').value=u.requiredPreviousVersion||'';document.querySelector('#routeUpdatePrice').value=u.price||'';document.querySelector('#routeUpdateDescription').value=u.description||'';document.querySelector('#routeUpdateUrl').value=u.url||'';document.querySelector('#routeUpdatePath').value=u.downloadPath||'';document.querySelector('#routeUpdateActive').checked=u.active===true;document.querySelector('#routeUpdateFormTitle').textContent='Edit pilihan update';form.scrollIntoView({behavior:'smooth',block:'start'})}if(disable){if(!confirm('Nonaktifkan pilihan update ini?'))return;fb.deleteRouteUpdate(disable.dataset.routeDisable).then(()=>{toast('Pilihan update dinonaktifkan.');load()}).catch(err=>toast(err.message))}});load()}
function bindCommerce(){legacyBindCommerce();if(location.hash.split('?')[0]==='#account'&&window.JGTCFirebase?.currentUser){loadCustomerDashboard();document.querySelector('#refreshCustomerDashboard')?.addEventListener('click',loadCustomerDashboard)}document.querySelector('#refreshSalesSummary')?.addEventListener('click',loadAdminSalesSummary);document.querySelectorAll('[data-add-route-update]').forEach(b=>b.addEventListener('click',()=>{const u=routeUpdateCache.get(b.dataset.addRouteUpdate);if(!u||!u.eligible){toast('Update ini tidak memenuhi syarat akun kamu.');return}const ids=getRouteCart();if(ids.includes(u.id)){toast('Update ini sudah ada di keranjang.');return}setRouteCart([...ids,u.id]);saveRouteCartMeta(u);toast('Update rute ditambahkan ke keranjang.');location.hash='cart'}));document.querySelectorAll('[data-remove-route-update]').forEach(b=>b.addEventListener('click',()=>{setRouteCart(getRouteCart().filter(id=>id!==b.dataset.removeRouteUpdate));render()}));}
function cartPage(){const items=getCart().map(id=>addons.find(a=>a.id===id)).filter(Boolean),updates=routeCartItems(),total=items.reduce((n,a)=>n+priceNumber(a.price),0)+updates.reduce((n,u)=>n+Number(u.price||0),0),count=items.length+updates.length;return pageShell('Keranjang Belanja','PEMBELIAN',`${count} item dipilih.`,count?`<div class="cart-layout"><div class="cart-items">${items.map(a=>`<article class="cart-item"><img src="${imgFor(a)}" alt=""><div><b>${escapeHtml(a.title)}</b><small>${escapeHtml(a.category)}</small><strong>${escapeHtml(a.price||'Harga belum diatur')}</strong></div><button class="mini-btn danger" data-remove-cart="${escapeHtml(a.id)}">Hapus</button></article>`).join('')}${updates.map(u=>`<article class="cart-item route-cart-item"><div class="route-cart-icon">↻</div><div><b>${escapeHtml(u.routeTitle||'Rute')}</b><small>Update ${escapeHtml(u.version)} · dari versi ${escapeHtml(u.requiredPreviousVersion)}</small><strong>${money(u.price)}</strong></div><button class="mini-btn danger" data-remove-route-update="${escapeHtml(u.id)}">Hapus</button></article>`).join('')}</div><aside class="cart-summary"><h2>Ringkasan</h2><p>${count} item</p><strong class="cart-total">${money(total)}</strong><button class="button button-primary" id="goCheckout" type="button">Lanjut ke checkout</button></aside></div>`:'<div class="empty-state">Keranjang masih kosong. <a href="#rute-indonesia">Jelajahi katalog</a>.</div>')}
function checkoutPage(){const items=getCart().map(id=>addons.find(a=>a.id===id)).filter(Boolean),updates=routeCartItems(),count=items.length+updates.length;if(!count)return pageShell('Checkout','PEMBELIAN','Keranjang kosong.','<div class="empty-state"><a href="#home">Kembali ke katalog</a></div>');const total=items.reduce((n,a)=>n+priceNumber(a.price),0)+updates.reduce((n,u)=>n+Number(u.price||0),0),user=window.JGTCFirebase?.currentUser;if(!user)return pageShell('Login diperlukan','CHECKOUT','Masuk atau buat akun untuk melanjutkan pesanan.','<div class="info-panel"><a class="button button-primary" href="#account">Login / Daftar pembeli</a></div>');return pageShell('Checkout','KONFIRMASI PESANAN','Periksa kembali produk dan update rute sebelum membuat pesanan.',`<div class="checkout-layout"><form id="checkoutForm" class="admin-form"><h2>Data pembeli</h2><label>Nama<input value="${escapeHtml(user.displayName||'')}" readonly></label><label>Email<input value="${escapeHtml(user.email||'')}" readonly></label><label>Catatan pesanan (opsional)<textarea id="orderNote" rows="3" maxlength="500" placeholder="Catatan untuk admin"></textarea></label><div class="info-panel"><b>Metode pembayaran: Transfer manual</b><p>Harga akhir dan kelayakan update rute akan diperiksa ulang oleh server sebelum pesanan dibuat.</p></div><button class="button button-primary" type="submit" id="createOrderBtn">Buat pesanan</button><p id="checkoutError" class="small" role="alert"></p></form><aside class="cart-summary"><h2>Ringkasan pesanan</h2>${items.map(a=>`<p>${escapeHtml(a.title)} <b>${money(priceNumber(a.price))}</b></p>`).join('')}${updates.map(u=>`<p>Update ${escapeHtml(u.routeTitle)} v${escapeHtml(u.version)} <b>${money(u.price)}</b></p>`).join('')}<hr><strong class="cart-total">${money(total)}</strong></aside></div>`)}

async function loadCustomerDashboard(){const box=document.querySelector('#customerDashboardContent'),fb=window.JGTCFirebase;if(!box||!fb?.currentUser)return;box.innerHTML='<div class="empty-state">Memuat data akun...</div>';try{const d=await fb.getCustomerDashboard();const moneyFmt=n=>money(Number(n)||0);box.innerHTML=`<div class="dashboard-stat"><small>Pesanan terbaru</small><b>${d.orders.length}</b><span>maks. 10 transaksi terakhir</span></div><div class="dashboard-stat"><small>Produk dimiliki</small><b>${d.ownerships.length}</b><span>hak akses tercatat</span></div><div class="dashboard-stat"><small>Notifikasi belum dibaca</small><b>${d.unreadCount}</b><span>pembaruan akun</span></div><div class="dashboard-panel"><h3>Notifikasi</h3>${d.notifications.length?d.notifications.map(n=>`<article class="notification-row ${n.read?'is-read':''}"><b>${escapeHtml(n.title)}</b><small>${escapeHtml(n.message)}</small><span>${n.createdAt?new Date(n.createdAt).toLocaleString('id-ID'):'Baru'}</span></article>`).join(''):'<p class="muted small">Belum ada notifikasi.</p>'}<button class="mini-btn" id="markNotificationsRead" type="button" ${d.unreadCount?'':'disabled'}>Tandai semua dibaca</button></div><div class="dashboard-panel"><h3>Pesanan terbaru</h3>${d.orders.length?d.orders.map(o=>`<article class="notification-row"><b>${escapeHtml(o.orderNumber)}</b><small>${escapeHtml(o.items.map(i=>i.title).join(', '))}</small><span>${moneyFmt(o.total)} · ${escapeHtml(o.status)}</span></article>`).join(''):'<p class="muted small">Belum ada pesanan.</p>'}<a class="text-link" href="#orders">Buka riwayat lengkap →</a></div>`;document.querySelector('#markNotificationsRead')?.addEventListener('click',async()=>{try{await fb.markNotificationsRead(d.notifications.filter(n=>!n.read).map(n=>n.id));loadCustomerDashboard()}catch(e){toast(e.message)}})}catch(e){box.innerHTML=`<div class="empty-state">${escapeHtml(e.message||'Gagal memuat dashboard.')}</div>`}}
async function loadAdminSalesSummary(){const box=document.querySelector('#salesSummaryContent'),fb=window.JGTCFirebase;if(!box||!fb?.isAdmin)return;box.innerHTML='<div class="empty-state">Memuat statistik...</div>';try{const d=await fb.getAdminSalesSummary();box.innerHTML=`<div class="dashboard-stat"><small>Total pendapatan lunas</small><b>${money(d.revenue)}</b><span>dari ${d.sampledOrders} pesanan yang diperiksa</span></div><div class="dashboard-stat"><small>Pesanan lunas</small><b>${d.paidOrders}</b><span>transaksi disetujui</span></div><div class="dashboard-stat"><small>Menunggu proses</small><b>${d.pendingOrders}</b><span>pembayaran / verifikasi</span></div><div class="dashboard-stat"><small>Rata-rata pesanan</small><b>${money(d.averageOrder)}</b><span>nilai per pesanan lunas</span></div><div class="dashboard-panel"><h3>Pendapatan per hari</h3>${d.dailyRevenue.length?d.dailyRevenue.map(x=>`<div class="sales-line"><span>${escapeHtml(x.date)}</span><b>${money(x.total)}</b></div>`).join(''):'<p class="muted small">Belum ada transaksi lunas.</p>'}</div>`}catch(e){box.innerHTML=`<div class="empty-state">${escapeHtml(e.message||'Statistik tidak dapat dimuat.')}</div>`}}

function render(){if(!catalogFromCloud)addons=getAddons();const raw=location.hash.slice(1)||'home';const route=raw.split('?')[0];document.title=(routeInfo[route]?.title||({home:'Halaman Muka',tools:'Alat Bantu KUID',tips:'Tips Instalasi',contact:'Hubungi Admin',news:'Apa yang Baru',admin:'Panel Admin','route-updates':'Update Rute'}[route]||'JGTC REBORN'))+' — JGTC REBORN';if(route==='home'){main.innerHTML=homeMarkup;const y=document.querySelector('#year');if(y)y.textContent=new Date().getFullYear();const updatesList=document.querySelector('#updatesList');if(updatesList)updatesList.innerHTML=addons.slice(0,4).map(a=>`<article class="update-item"><div class="update-date">${escapeHtml(a.date||'KATALOG')}</div><div><b>${escapeHtml(a.title)}</b><small>${escapeHtml(a.desc)}</small><a href="#${categories.find(c=>c.name===a.category)?.id||'konten-freeware'}">Lihat kategori ↗</a></div></article>`).join('');const regionCards=document.querySelector('#regionCards');if(regionCards)regionCards.innerHTML=categories.map((c,i)=>`<a class="region-card" href="#${c.id}"><div class="region-art"><img loading="lazy" src="${c.image}" alt="${escapeHtml(c.name)}"><span class="region-number">0${i+1}</span></div><div class="region-body"><span class="tag">KATEGORI ADD-ON</span><h3>${escapeHtml(c.name)}</h3><p>${escapeHtml(c.desc)}</p><span class="card-link">Jelajahi koleksi <span>→</span></span></div></a>`).join('');}else if(routeInfo[route])main.innerHTML=catalogPage(route);else if(route==='route-updates'){main.innerHTML=routeUpdatesPage();loadRouteUpdatesPage()}else if(route==='tools')main.innerHTML=toolsPage();else if(route==='tips')main.innerHTML=tipsPage();else if(route==='contact')main.innerHTML=contactPage();else if(route==='admin'){main.innerHTML=adminPage()+`<section class="section-block admin-sales"><div class="section-heading"><div><span class="section-kicker">ANALITIK TOKO</span><h2>Ringkasan penjualan</h2></div><button class="mini-btn" id="refreshSalesSummary" type="button">Muat ulang</button></div><div id="salesSummaryContent" class="dashboard-grid"><div class="empty-state">Memuat statistik...</div></div></section>`;bindAdmin();bindPaymentAdmin();loadAdminSalesSummary()}else if(route==='product'){const id=new URLSearchParams(raw.includes('?')?raw.slice(raw.indexOf('?')+1):'').get('id')||'';main.innerHTML=productDetailPage(id)}else if(route==='cart')main.innerHTML=cartPage();else if(route==='checkout')main.innerHTML=checkoutPage();else if(route==='account')main.innerHTML=accountPage();else if(route==='payment'){main.innerHTML=paymentPage(new URLSearchParams(raw.includes('?')?raw.slice(raw.indexOf('?')+1):'').get('id')||'')}else if(route==='orders'){main.innerHTML=pageShell('Riwayat Pembelian','AKUN SAYA','Daftar pesanan dari akun kamu.','<div id="ordersList" class="orders-list"><div class="empty-state">Memuat riwayat pembelian...</div></div>');}else if(route==='news')main.innerHTML=pageShell('Apa yang Baru?','BERITA & PEMBARUAN','Konten katalog terbaru.',`<div class="catalog-grid">${cardList(addons.slice(0,12))}</div>`);else if(route.startsWith('search')){const q=new URLSearchParams(raw.includes('?')?raw.slice(raw.indexOf('?')+1):'').get('q')||'';main.innerHTML=searchPage(q)}else main.innerHTML=pageShell('Halaman tidak ditemukan','404','Halaman yang kamu cari tidak tersedia.','<div class="info-panel"><a class="button button-primary" href="#home">Kembali ke halaman muka</a></div>');document.querySelectorAll('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===route));if(route==='cart'||route==='checkout')refreshRouteCartMeta(route);updateCartCount();bindCommerce();closeMenu();}
function closeMenu(){document.querySelector('#sidebar').classList.remove('open');document.querySelector('#scrim').classList.remove('show');document.querySelector('#menuToggle').setAttribute('aria-expanded','false');document.body.style.overflow=''}
function openMenu(){document.querySelector('#sidebar').classList.add('open');document.querySelector('#scrim').classList.add('show');document.querySelector('#menuToggle').setAttribute('aria-expanded','true');document.body.style.overflow='hidden'}
document.querySelector('#menuToggle').addEventListener('click',openMenu);document.querySelector('#closeMenu').addEventListener('click',closeMenu);document.querySelector('#scrim').addEventListener('click',closeMenu);
document.querySelectorAll('[data-expand]').forEach(btn=>btn.addEventListener('click',()=>{const sub=document.querySelector(`[data-subnav="${btn.dataset.expand}"]`);const open=sub.classList.toggle('open');btn.setAttribute('aria-expanded',String(open))}));
document.querySelector('#searchForm').addEventListener('submit',e=>{e.preventDefault();const q=document.querySelector('#searchInput').value.trim();if(!q){toast('Masukkan kata kunci pencarian.');return}location.hash='search?q='+encodeURIComponent(q);document.querySelector('#searchInput').blur()});
document.querySelector('#searchInput').addEventListener('focus',()=>document.querySelector('#searchForm').classList.add('expanded'));document.querySelector('#searchInput').addEventListener('blur',()=>{if(!document.querySelector('#searchInput').value)document.querySelector('#searchForm').classList.remove('expanded')});
document.addEventListener('click',e=>{const btn=e.target.closest('[data-filter]');if(btn){document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b===btn));const filter=btn.dataset.filter;document.querySelectorAll('#catalogGrid .addon-card').forEach(card=>{card.style.display=filter==='Semua'||card.textContent.includes(filter)||card.querySelector('.pill')?.textContent===filter?'':'none'});}});
document.addEventListener('input',e=>{if(e.target.id==='catalogSearch'){const q=e.target.value.toLowerCase();document.querySelectorAll('#catalogGrid .addon-card').forEach(card=>card.style.display=card.textContent.toLowerCase().includes(q)?'':'none')}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'auto'})});
render();
if(window.JGTCFirebase){
  const fb=window.JGTCFirebase;
  fb.onAuth(()=>{refreshAdminNav();const current=(location.hash.slice(1)||'home').split('?')[0];if(['admin','account','checkout','orders','route-updates'].includes(current))render();});
  if(fb.enabled){
    fb.subscribeCatalog(items=>{addons=items;catalogFromCloud=true;localStorage.setItem(STORAGE_KEY,JSON.stringify(items));render();},error=>{console.error('Firestore read error:',error);toast('Gagal memuat katalog Firebase: '+error.message);});
  } else if(fb.configured===false){console.info('Firebase belum dikonfigurasi. Website menampilkan data contoh lokal sampai konfigurasi Firebase diisi.');}
}
refreshAdminNav();
